// Map: one shape layer per country set; stroke draws on, then the fill fades in.
function mapLayer(c, name, rings, col, t0, dur, opt) {
    opt = opt || {};
    var l = shapeLayer(c, name, [0, 0]);
    newGroup(l, "Land");
    for (var i = 0; i < rings.length; i++) path(l, "Land", rings[i], true);
    fill(l, "Land", col, 0);
    keys(last(l, "Land").property("ADBE Vector Fill Opacity"), [t0 + dur * 0.55, t0 + dur + 0.3], [0, 100], 50);
    if (opt.draw !== false) {
        stroke(l, "Land", opt.strokeCol || col, opt.sw || 3);
        trimIn(l, "Land", t0, dur);
    }
    if (opt.fade !== false) fadeRight(l, opt.fadeX || 1180);
    return l;
}
function dot(c, name, xy, t0, col, r) {
    var l = shapeLayer(c, name, xy);
    newGroup(l, "D"); ellipse(l, "D", [r || 22, r || 22]); fill(l, "D", col || CFG.ORANGE); stroke(l, "D", CFG.WHITE, 4);
    newGroup(l, "Ring"); ellipse(l, "Ring", [22, 22]); stroke(l, "Ring", col || CFG.ORANGE, 3);
    last(l, "Ring").property("ADBE Vector Stroke Width").setValue(3);
    items(l, "Ring").property(1).property("ADBE Vector Ellipse Size").expression = 'var t=Math.max(0,time-' + t0 + ')%1.6/1.6;[22+90*t,22+90*t]';
    grp(l, "Ring").property("ADBE Vector Transform Group").property("ADBE Vector Group Opacity").expression = 'time<' + t0 + '?0:100*(1-(time-' + t0 + ')%1.6/1.6)';
    popIn(l, t0);
    return l;
}
function bg(c, dark) { var it = BG[dark ? 1 : 0]; if (!it) return; c.layers.add(it); var l = c.layer(1); l.name = "BG"; l.moveToEnd(); }

// Camera rig: everything except captions is parented to a null that slowly pushes in, then dives into the focal point at the cut.
function rig(c, focal, dive) {
    var n = c.layers.addNull(c.duration); n.name = "RIG";
    tr(n).property("ADBE Anchor Point").setValue([50, 50]);
    P(n).setValue(focal);
    for (var i = c.numLayers; i >= 1; i--) {
        var l = c.layer(i);
        if (l === n || l.name === "RIG" || l.name === "BG" || /^(CAP|BUL|SRC)/.test(l.name) || l.parent) continue;
        try { l.parent = n; } catch (e) {}
    }
    var d = c.duration, te = Math.max(1, d - CFG.WIPE - 0.1);
    keys(S(n), [0, te, d], [[100, 100], [106, 106], [dive || 135, dive || 135]], 40);
    try { var ne = S(n).value.length || 3, ea = []; for (var q = 0; q < ne; q++) ea.push(new KeyframeEase(0, 85)); S(n).setTemporalEaseAtKey(3, ea, ea); } catch (e) {}
    P(n).expression = '[value[0]+Math.sin(time*0.8)*3, value[1]+Math.cos(time*0.6)*2]';
    return n;
}

