function photoLayer(c, name, cx, cy, w, h) {
    if (!PHOTO) { var ph = c.layers.addSolid([0.4, 0.4, 0.4], name + " (PHOTO MISSING)", w, h, 1); P(ph).setValue([cx, cy]); return ph; }
    c.layers.add(PHOTO); var l = c.layer(1); l.name = name;
    var s = Math.max(w / PHOTO.width, h / PHOTO.height) * 100; S(l).setValue([s, s]); P(l).setValue([cx, cy]);
    var hw = w / 2 / (s / 100), hh = h / 2 / (s / 100), mx = PHOTO.width / 2, my = PHOTO.height / 2;
    addMask(l, [[mx - hw, my - hh], [mx + hw, my - hh], [mx + hw, my + hh], [mx - hw, my + hh]]);
    try {   // monochrome, slightly crushed — hides the small source size and fits the "shadow" theme
        l.property("ADBE Effect Parade").addProperty("ADBE Tint");
        var tn = function () { return l.property("ADBE Effect Parade").property(1); };
        tn().property(1).setValue([0.08, 0.08, 0.08, 1]); tn().property(2).setValue([0.95, 0.95, 0.95, 1]); tn().property(3).setValue(100);
    } catch (e) {}
    return l;
}

